INSERT INTO wisdom_shorts (id,title,short,pullquote,source_author,source_url,source_type,themes,emotional_states,cognitive_patterns,values,enneagram_resonance,cognitive_style,depth,image_url,image_prompt) VALUES
('ap_ego_hunger','The Ego''s Hunger Cannot Be Fed','The ego is not a thing you have — it is a pattern of seeking. It wants security, approval, continuity. And the strange thing is, the more you feed it, the hungrier it becomes. Satisfaction is not in its vocabulary. This is not a flaw in you — it is the nature of the conditioned mind. The only freedom is to see the hunger clearly, not to try to satiate it.','The ego is not a thing you have — it is a pattern of seeking.','Acharya Prashant','https://www.youtube.com/c/AcharyaPrashant','talk',ARRAY['ego','desire','conditioning','freedom'],ARRAY['anxious','restless','unfulfilled','striving'],ARRAY['approval-seeking','future-orientation','catastrophising'],ARRAY['authenticity','freedom','clarity'],ARRAY[2,3,6,9],ARRAY['analytical','reflective'],'mid',NULL,NULL),
('ap_comparison','You Cannot Suffer Without Comparing','Every instance of suffering involves a comparison — this is how things are, and this is how they should be. Pain arises from the gap between the two. Watch any grievance and you''ll find the hidden comparison underneath it. Who decided how things should be? A conditioned mind, shaped by fear, memory, and social expectation. What if you met this moment without the ''should''?','Every instance of suffering involves a comparison.','Acharya Prashant','https://www.youtube.com/c/AcharyaPrashant','talk',ARRAY['comparison','suffering','expectations','acceptance'],ARRAY['resentful','disappointed','envious','comparing'],ARRAY['should-statements','comparison','all-or-nothing'],ARRAY['authenticity','clarity','peace'],ARRAY[1,2,3,4],ARRAY['reflective','analytical'],'mid',NULL,NULL),
('ap_love_attachment','Most Relationships Are Negotiations Between Two Fears','What most people call love is actually need. ''I love you'' often means ''I need you to be a certain way so I can feel secure.'' Real love doesn''t demand. It doesn''t fear the other person''s freedom. It doesn''t shrink when the other person grows. Most relationships are negotiations between two fears — one fear trying to get something from another fear.','Most relationships are negotiations between two fears.','Acharya Prashant','https://www.youtube.com/c/AcharyaPrashant','talk',ARRAY['love','attachment','relationships','ego','freedom'],ARRAY['jealous','possessive','insecure','dependent'],ARRAY['mind-reading','emotional-reasoning','personalisation'],ARRAY['love','freedom','authenticity'],ARRAY[2,4,6,8],ARRAY['reflective','analytical'],'mid',NULL,NULL),
('jk_observer_observed','The Thinker and the Thought Are the Same Movement','We believe there is a thinker who has thoughts — a self that observes problems and tries to solve them. But look carefully: when you observe a thought, who is doing the observing? It is another thought. The observer is the observed. If the thinker is the thought, then the ''me'' that is suffering is itself the suffering — not a separate entity that needs to be fixed.','The observer is the observed.','J. Krishnamurti','https://www.jkrishnamurti.org','talk',ARRAY['consciousness','self-inquiry','thought','identity'],ARRAY['confused','analytical','stuck','self-critical'],ARRAY['rumination','self-blame','over-analysis'],ARRAY['truth','clarity','self-understanding'],ARRAY[4,5,6,1],ARRAY['analytical','philosophical'],'deep',NULL,NULL),
('jk_relationship_mirror','Every Relationship Is a Mirror','When you react strongly to someone — with anger, admiration, or resentment — you are not seeing them. You are seeing the projection of your own conditioning. The person who irritates you is reflecting something about yourself you haven''t examined. The person you idealize is carrying a quality you want but don''t claim. Every relationship is an invitation to self-knowledge.','The person who irritates you is reflecting something about yourself you haven''t examined.','J. Krishnamurti','https://www.jkrishnamurti.org','talk',ARRAY['relationships','projection','self-knowledge','conflict'],ARRAY['resentful','conflicted','irritable','jealous'],ARRAY['projection','personalisation','mind-reading'],ARRAY['self-awareness','truth','growth'],ARRAY[2,4,6,8,1],ARRAY['analytical','reflective'],'mid',NULL,NULL),
('aw_you_are_universe','You Didn''t Come Into This World — You Came Out of It','You are not a separate self that got dropped into existence. You are the universe becoming aware of itself in this particular form — like a wave from the ocean. The anxiety of separation — of being a small, vulnerable self against a large, indifferent world — rests on a mistaken premise. You are not in nature. You are nature.','You didn''t come into this world. You came out of it, like a wave from the ocean.','Alan Watts','https://www.youtube.com/@AlanWattsOrganization','talk',ARRAY['identity','separation','existence','consciousness','non-duality'],ARRAY['lonely','anxious','existential','lost','disconnected'],ARRAY['personalisation','catastrophising'],ARRAY['meaning','connection','wonder'],ARRAY[4,5,7,9],ARRAY['intuitive','holistic'],'deep',NULL,NULL),
('aw_backwards_law','The Harder You Try to Control, the Less Control You Have','The things we most want — love, sleep, pleasure, confidence — cannot be forced. The moment you try to force them, they retreat. The harder you try to be happy, the less happy you become. This is the backwards law: in many domains, the path runs in the opposite direction of trying. The way forward is often a kind of relaxed allowing.','The things we most want cannot be forced. The moment you try to force them, they retreat.','Alan Watts','https://www.youtube.com/@AlanWattsOrganization','talk',ARRAY['control','paradox','acceptance','flow','effort'],ARRAY['frustrated','striving','controlling','anxious','stuck'],ARRAY['all-or-nothing','perfectionism','over-control'],ARRAY['freedom','ease','authenticity'],ARRAY[1,3,5,6,8],ARRAY['intuitive','holistic'],'mid',NULL,NULL),
('osho_witnessing','You Are Not Your Mood — You Are the Sky','The weather changes — rain, sun, storm, calm. The sky does not change. You are the sky, not the weather. When you are angry, the anger is happening in you, but you are not the anger. The moment you understand this, the quality of your inner life shifts. You can watch the storm without becoming the storm. This is what meditation is: a larger presence that holds the feeling.','You are the sky, not the weather.','Osho','','book',ARRAY['witnessing','meditation','emotions','awareness','equanimity'],ARRAY['overwhelmed','reactive','anxious','emotional','turbulent'],ARRAY['emotional-reasoning','catastrophising','rumination'],ARRAY['peace','self-awareness','freedom'],ARRAY[2,4,6,8,9],ARRAY['intuitive','experiential'],'entry',NULL,NULL),
('osho_aloneness','Loneliness Is the Absence of the Other — Aloneness Is the Presence of Yourself','People run from aloneness because they confuse it with loneliness. Loneliness is a wound: you feel incomplete without someone to fill the void. Aloneness is a fullness: you are so present with yourself that there is no void to fill. Most people never discover aloneness because they are too busy escaping loneliness — filling every silent moment with distraction and noise.','Loneliness is the absence of the other. Aloneness is the presence of yourself.','Osho','','book',ARRAY['solitude','loneliness','aloneness','self-relationship','presence'],ARRAY['lonely','isolated','disconnected','restless','bored'],ARRAY['avoidance','distraction','emotional-reasoning'],ARRAY['self-sufficiency','presence','depth'],ARRAY[4,5,9,2],ARRAY['intuitive','experiential'],'mid',NULL,NULL),
('stoic_dichotomy','The Stoic''s Only Question: Is This in My Control?','Epictetus, born a slave, built an entire philosophy on one distinction: some things are in our power, and some things are not. In our power: our judgements, our intentions, our responses. Not in our power: our body, reputation, property, other people''s actions. Almost all human suffering, he argued, comes from mixing these two categories — grieving over what was never ours to control.','Almost all suffering comes from grieving over what was never ours to control.','Epictetus','','book',ARRAY['control','acceptance','resilience','equanimity','freedom'],ARRAY['frustrated','anxious','controlling','resentful','overwhelmed'],ARRAY['over-control','catastrophising','all-or-nothing'],ARRAY['freedom','integrity','resilience'],ARRAY[1,6,8,3],ARRAY['analytical','first-principles'],'entry',NULL,NULL),
('stoic_marcus_morning','Expect Difficult People — Then You Won''t Be Surprised','Marcus Aurelius began each day with a reminder: ''In the morning when you rise unwillingly, let this thought be present: I am rising to the work of a human being.'' He also noted: ''When you wake up in the morning, tell yourself: The people I deal with today will be meddling, ungrateful, arrogant, dishonest, jealous and surly.'' Not as cynicism — but as preparation. Surprise is the enemy of equanimity.','Surprise is the enemy of equanimity.','Marcus Aurelius','','book',ARRAY['resilience','expectations','acceptance','people','equanimity'],ARRAY['frustrated','disappointed','resentful','conflicted'],ARRAY['all-or-nothing','personalisation','mind-reading'],ARRAY['equanimity','integrity','wisdom'],ARRAY[1,6,8,9],ARRAY['analytical','pragmatic'],'entry',NULL,NULL),
('stoic_seneca_time','It''s Not That We Have Too Little Time — We Waste Too Much of It','Seneca opens his essay on time with a provocation: we are not given a short life, we make it short. The time we actually have is ample — if only we would use it. He identified the ways we squander it: postponing life to some future date, spending it on other people''s priorities, consuming it in distraction and shallow pleasure. ''Omnia aliena sunt, tempus tantum nostrum est.'' All things are alien to us; time alone is ours.','All things are alien to us; time alone is ours.','Seneca','','book',ARRAY['time','urgency','priorities','meaning','presence'],ARRAY['purposeless','distracted','drifting','unfulfilled','anxious'],ARRAY['avoidance','future-orientation','procrastination'],ARRAY['meaning','intentionality','presence'],ARRAY[3,5,7,9],ARRAY['analytical','pragmatic'],'mid',NULL,NULL),
('camus_absurd','The Absurd Is Not a Problem to Be Solved — It Is a Tension to Be Lived','Camus identified the absurd as the collision between the human need for meaning and the universe''s silent indifference. The temptation is to resolve this tension — through religion, ideology, or suicide. But Camus''s answer was a third option: revolt. Keep the tension alive. Don''t escape it. Acknowledge the absurdity and live fully within it anyway. ''One must imagine Sisyphus happy.''','One must imagine Sisyphus happy.','Albert Camus','','book',ARRAY['meaning','absurdity','existence','suffering','rebellion'],ARRAY['existential','purposeless','hopeless','lost','nihilistic'],ARRAY['all-or-nothing','catastrophising','learned-helplessness'],ARRAY['meaning','courage','freedom'],ARRAY[4,5,7,9],ARRAY['philosophical','narrative'],'deep',NULL,NULL),
('sartre_bad_faith','Bad Faith: Pretending You Have No Choice When You Do','Sartre described ''bad faith'' as the lie we tell ourselves that we have no options. The waiter who acts like a machine — as if waiting tables defines his entire being — is in bad faith. The person who says ''I had no choice'' when they had several is in bad faith. For Sartre, the terror of freedom is that we are always choosing. Even choosing not to choose is a choice. This is both the most disturbing and most liberating idea in philosophy.','Even choosing not to choose is a choice.','Jean-Paul Sartre','','book',ARRAY['freedom','responsibility','identity','choice','authenticity'],ARRAY['stuck','victimized','trapped','resigned','passive'],ARRAY['learned-helplessness','all-or-nothing','avoidance'],ARRAY['freedom','responsibility','authenticity'],ARRAY[1,4,6,9],ARRAY['philosophical','analytical'],'deep',NULL,NULL),
('frankl_meaning_suffering','When You Cannot Choose the Situation, Choose the Stance','Between stimulus and response there is a space. In that space is our power to choose our response. Frankl discovered this not in a lecture hall but in Auschwitz — that everything can be taken from a person but one thing: the last of the human freedoms, to choose one''s attitude in any given set of circumstances.','Everything can be taken from a person but one thing: the last of the human freedoms.','Viktor Frankl','','book',ARRAY['meaning','suffering','freedom','resilience','attitude'],ARRAY['hopeless','trapped','victimized','stuck','grieving'],ARRAY['learned-helplessness','all-or-nothing','personalisation'],ARRAY['meaning','freedom','dignity'],ARRAY[1,4,6,8],ARRAY['narrative','analytical'],'mid',NULL,NULL),
('frankl_unbearable','The Unbearable Is Not Pain — It Is Pain Without Meaning','Frankl observed that people could endure almost any suffering if they had a reason for it. When a person finds a purpose large enough — love for another, an unfinished work, a commitment — the suffering does not disappear, but it becomes bearable. The unbearable is not pain. The unbearable is pain without meaning.','The unbearable is not pain. The unbearable is pain without meaning.','Viktor Frankl','','book',ARRAY['suffering','meaning','purpose','resilience'],ARRAY['hopeless','grieving','purposeless','lost','trapped'],ARRAY['learned-helplessness','catastrophising'],ARRAY['meaning','resilience','purpose'],ARRAY[4,6,9,1],ARRAY['narrative','philosophical'],'deep',NULL,NULL),
('nietzsche_will','What Doesn''t Kill You Doesn''t Automatically Make You Stronger','Nietzsche''s famous line is often misread as comfort. What he actually said was more demanding: suffering can strengthen — but only if you have the will to make it mean something. Suffering without interpretation is just damage. The difference between trauma that destroys and adversity that forges is not the event itself but the relationship the person builds with it. Growth after hardship is an active choice, not a passive outcome.','Suffering without interpretation is just damage.','Friedrich Nietzsche','','book',ARRAY['suffering','resilience','meaning','strength','will'],ARRAY['stuck','wounded','hopeless','resigned','struggling'],ARRAY['learned-helplessness','all-or-nothing','personalisation'],ARRAY['strength','meaning','growth'],ARRAY[1,4,8,3],ARRAY['philosophical','analytical'],'mid',NULL,NULL),
('ns_default_mode','Your Brain''s Resting State Is Making You Miserable','When you''re not focused on a task, your brain doesn''t rest — it activates its Default Mode Network: a circuit that replays the past, anticipates the future, and thinks about yourself in relation to others. Studies consistently show: the more time people spend mind-wandering, the less happy they report being — even when the wandering is about pleasant things. Presence is not a spiritual luxury. It is a neurological imperative.','The more time people spend mind-wandering, the less happy they report being.','Matthew Killingsworth & Daniel Gilbert (Harvard)','','paper',ARRAY['mind-wandering','presence','rumination','happiness','neuroscience'],ARRAY['anxious','ruminating','distracted','overthinking','restless'],ARRAY['rumination','future-orientation','past-focus'],ARRAY['presence','clarity','wellbeing'],ARRAY[4,5,6,9],ARRAY['analytical','evidence-based'],'entry',NULL,NULL),
('ns_neuroplasticity','Every Thought You Repeat Is Literally Rewiring Your Brain','Neurons that fire together wire together. Every time you engage in a thought pattern — self-criticism, catastrophising, gratitude, curiosity — the neural pathway for that pattern becomes more efficient. Your brain is not fixed. It is remodeling itself constantly, based on what you attend to. Your habitual thoughts are not just passing moods. They are infrastructure. You are building something with every repetition.','Your habitual thoughts are not just passing moods. They are infrastructure.','Donald Hebb / Modern Neuroscience','','paper',ARRAY['habits','neuroplasticity','thought-patterns','change'],ARRAY['stuck','self-critical','hopeless','motivated'],ARRAY['rumination','self-blame','perfectionism'],ARRAY['growth','awareness','change'],ARRAY[1,5,6,9],ARRAY['analytical','evidence-based'],'entry',NULL,NULL),
('ns_stress_decisions','Under Stress, Your Brain Becomes a Threat-Detection Machine','When you''re under acute stress, the amygdala suppresses the prefrontal cortex — the region responsible for nuanced thinking, future planning, and perspective-taking. This is why decisions made in anger, fear, or overwhelm are so often regretted. The brain under stress is doing exactly what it evolved to do: move fast. But ''move fast'' was built for a predator on the savannah, not for a difficult conversation or a career decision.','''Move fast'' was built for a predator — not a career decision.','Amy Arnsten (Yale Neuroscience)','','paper',ARRAY['stress','decision-making','emotions','nervous-system'],ARRAY['stressed','overwhelmed','reactive','panicking','anxious'],ARRAY['catastrophising','all-or-nothing','emotional-reasoning'],ARRAY['clarity','composure','self-awareness'],ARRAY[1,6,8,2],ARRAY['analytical','evidence-based'],'entry',NULL,NULL),
('ns_creativity_rest','Rest Is Where Insight Happens','The greatest leaps in understanding rarely happen at the desk. They happen when you step away from the desk. The default mode network — active during rest — makes connections between disparate brain regions that focused attention suppresses. Archimedes in the bath. Newton under the tree. The shower revelation. Rest is not laziness. It is where the non-obvious becomes obvious.','Rest is not the absence of work. It is where insight happens.','Rex Jung / Roger Beaty (Creativity Neuroscience)','','paper',ARRAY['creativity','rest','insight','productivity'],ARRAY['stuck','blocked','frustrated','overthinking','unmotivated'],ARRAY['over-control','perfectionism','rumination'],ARRAY['creativity','balance','wisdom'],ARRAY[1,3,5,7],ARRAY['analytical','intuitive'],'entry',NULL,NULL),
('ns_damasio_emotion','You Cannot Make Good Decisions Without Emotions','Antonio Damasio studied patients with damage to the emotion centres of the brain. They were perfectly rational — high IQ, intact reasoning — but they couldn''t make decisions. They would deliberate endlessly without ever choosing. His conclusion: emotions are not the enemy of good thinking. They are required for it. The feeling of ''this matters'' or ''this is wrong'' is the signal that moves deliberation to action.','Emotions are not the enemy of good thinking. They are required for it.','Antonio Damasio','','book',ARRAY['emotions','decision-making','rationality','consciousness'],ARRAY['confused','detached','analytical','numb','overthinking'],ARRAY['over-analysis','emotional-suppression','avoidance'],ARRAY['self-awareness','wisdom','integration'],ARRAY[1,5,6,3],ARRAY['analytical','evidence-based'],'mid',NULL,NULL),
('ns_prediction_brain','Your Brain Is Not Reacting to the World — It Is Predicting It','Neuroscientist Lisa Feldman Barrett''s research overturns the idea that the brain passively reacts to the world. In fact, the brain is a prediction machine: it constantly generates models of what is about to happen, and only processes incoming data to update those models. What you perceive is not raw reality — it is your brain''s best guess, coloured by past experience. This is why two people can witness the same event and have completely different experiences.','What you perceive is not raw reality — it is your brain''s best guess.','Lisa Feldman Barrett','','book',ARRAY['perception','reality','bias','consciousness','prediction'],ARRAY['confused','conflicted','misunderstood','reactive'],ARRAY['personalisation','projection','mind-reading'],ARRAY['truth','self-awareness','clarity'],ARRAY[1,4,5,6],ARRAY['analytical','evidence-based'],'mid',NULL,NULL),
('nc_dopamine_wanting','Dopamine Is About Wanting, Not Having','Dopamine is widely misunderstood as the ''pleasure chemical.'' It is actually the wanting chemical. It drives you toward the reward, not the satisfaction of receiving it. The anticipation of a notification, a win, or an achievement floods you with dopamine — but the arrival of that thing often doesn''t. This is why modern life, engineered for maximum dopamine stimulation, is producing a generation that cannot sit still and cannot feel satisfied.','Dopamine drives you toward the reward — not the satisfaction of receiving it.','Kent Berridge & Terry Robinson (Neuroscience)','','paper',ARRAY['desire','motivation','addiction','satisfaction','dopamine'],ARRAY['restless','unfulfilled','addicted','striving','bored'],ARRAY['hedonic-adaptation','future-orientation','avoidance'],ARRAY['presence','contentment','clarity'],ARRAY[3,7,5,9],ARRAY['analytical','evidence-based'],'mid',NULL,NULL),
('nc_cortisol_chronic','Chronic Stress Shrinks the Brain — Literally','Cortisol in short bursts is useful — it sharpens focus and mobilises energy. But chronically elevated cortisol, the kind that comes from sustained psychological stress, damages the hippocampus (memory), thins the prefrontal cortex (judgement), and enlarges the amygdala (fear). The brain physically changes under prolonged stress. This is why it becomes progressively harder to think clearly, be patient, or feel hopeful when you''re burning out.','The brain physically changes under prolonged stress.','Robert Sapolsky (Stanford)','','book',ARRAY['stress','burnout','nervous-system','neuroscience','body'],ARRAY['burned-out','overwhelmed','anxious','foggy','hopeless'],ARRAY['catastrophising','rumination','all-or-nothing'],ARRAY['wellbeing','balance','recovery'],ARRAY[1,3,6,2],ARRAY['analytical','evidence-based'],'mid',NULL,NULL),
('nc_serotonin_status','Serotonin Is Not About Happiness — It Is About Status','Serotonin regulates mood, but its deeper function is social positioning. High serotonin is associated with feeling secure in your rank — not happy exactly, but settled, unafraid, not needing to prove anything. Low serotonin correlates with anxiety, vigilance, and the desperate need for approval. This is why comparison is so biochemically potent: every perceived loss of status is a literal serotonin drop. Social media is, in this sense, a daily assault on your neurochemistry.','Social media is a daily assault on your neurochemistry.','Jordan Peterson / Neuroscience Research','','book',ARRAY['status','comparison','approval','social-media','neuroscience'],ARRAY['comparing','anxious','insecure','approval-seeking','restless'],ARRAY['comparison','approval-seeking','social-evaluation'],ARRAY['authenticity','self-worth','freedom'],ARRAY[2,3,4,6],ARRAY['analytical','evidence-based'],'mid',NULL,NULL),
('nc_oxytocin_trust','Trust Is a Neurochemical — and It Can Be Built','Oxytocin is released through physical touch, sustained eye contact, shared vulnerability, and being truly heard. It produces trust, warmth, and belonging — and it is the antidote to cortisol. The single most reliable way to lower stress is human connection. Loneliness isn''t a feeling — it''s a physiological state that increases cortisol, inflammatory markers, and cardiovascular risk. We are not wired for isolation. Connection is maintenance, not luxury.','The single most reliable way to lower stress is human connection.','Paul Zak (Claremont Graduate University)','','paper',ARRAY['connection','trust','loneliness','stress','relationships'],ARRAY['lonely','isolated','disconnected','anxious','stressed'],ARRAY['avoidance','withdrawal','emotional-suppression'],ARRAY['connection','vulnerability','belonging'],ARRAY[2,4,5,9],ARRAY['relational','evidence-based'],'entry',NULL,NULL),
('bio_sapolsky_zebra','Zebras Don''t Get Ulcers — But You Do','Robert Sapolsky''s insight: a zebra on the savannah activates a stress response when chased by a lion, then — if it survives — switches it off completely. Humans activate the same physiological response to a lion, a job review, a social media argument, and a memory from three years ago. We are the only animals who can turn on the stress response just by thinking. And we leave it on. That sustained activation is what destroys us.','We are the only animals who can turn on the stress response just by thinking.','Robert Sapolsky','','book',ARRAY['stress','body','nervous-system','rumination','health'],ARRAY['stressed','anxious','overwhelmed','ruminating','burned-out'],ARRAY['rumination','catastrophising','past-focus'],ARRAY['wellbeing','presence','balance'],ARRAY[1,5,6,9],ARRAY['analytical','evidence-based'],'entry',NULL,NULL),
('bio_evolution_mismatch','Your Brain Was Built for a World That No Longer Exists','The human brain evolved over hundreds of thousands of years in small tribes, with immediate physical threats, high caloric scarcity, and deep social interdependence. Today it operates in a radically different environment — abundance, sedentariness, digital stimulation, social isolation — without having had time to adapt. Many modern ailments — anxiety, obesity, loneliness, distraction — are not character failures. They are evolutionary mismatches.','Many modern ailments are not character failures. They are evolutionary mismatches.','Evolutionary Psychology Research','','paper',ARRAY['evolution','modern-life','anxiety','health','adaptation'],ARRAY['anxious','overwhelmed','self-critical','stuck','bored'],ARRAY['self-blame','personalisation','catastrophising'],ARRAY['self-compassion','understanding','clarity'],ARRAY[1,3,6,9],ARRAY['analytical','systems-thinking'],'mid',NULL,NULL),
('bio_sleep_memory','Sleep Is Not Rest — It Is the Brain Doing Its Most Important Work','During sleep, the brain replays and consolidates the day''s experiences, clearing toxic waste products (including those linked to Alzheimer''s), processing emotional memories, and pruning unnecessary neural connections. Matthew Walker''s research shows that skimping on sleep impairs emotional regulation more than almost any other variable. You cannot think your way to emotional stability while sleep-deprived. Biology first.','You cannot think your way to emotional stability while sleep-deprived.','Matthew Walker (UC Berkeley)','','book',ARRAY['sleep','health','emotions','recovery','biology'],ARRAY['burned-out','irritable','anxious','foggy','reactive'],ARRAY['over-control','perfectionism','emotional-reasoning'],ARRAY['wellbeing','recovery','balance'],ARRAY[1,3,6,8],ARRAY['analytical','evidence-based'],'entry',NULL,NULL),
('bio_gut_brain','Your Gut Has More Neurons Than Your Spinal Cord','The enteric nervous system — the gut — contains approximately 100 million neurons and communicates directly with the brain via the vagus nerve. Around 90% of the signals travel from gut to brain, not the other way. Gut bacteria produce neurotransmitters including serotonin and GABA. The emerging field of psychobiotics shows that what you eat shapes how you feel — not metaphorically, but neurochemically. The mind-body separation was always a fiction.','The mind-body separation was always a fiction.','Michael Gershon / Gut-Brain Axis Research','','paper',ARRAY['body','mind-body','gut','health','neuroscience'],ARRAY['anxious','foggy','disconnected','overwhelmed','stuck'],ARRAY['mind-body-disconnect','all-or-nothing','avoidance'],ARRAY['wellbeing','integration','health'],ARRAY[1,5,9,6],ARRAY['evidence-based','holistic'],'mid',NULL,NULL),
('jung_shadow','What You Resist in Others, You Carry in Yourself','Jung called it the shadow: the parts of yourself that you have rejected, suppressed, or never developed — now living in your unconscious, projected onto the people who trigger you most. The traits that enrage you in others are often your own disowned qualities. The person you despise most is frequently your best mirror. Integration — owning your shadow — doesn''t make you dark. It makes you whole.','The person you despise most is frequently your best mirror.','Carl Jung','','book',ARRAY['shadow','projection','integration','self-knowledge','unconscious'],ARRAY['resentful','judgmental','irritable','disgusted','conflicted'],ARRAY['projection','personalisation','all-or-nothing'],ARRAY['self-awareness','integrity','wholeness'],ARRAY[1,4,6,8],ARRAY['reflective','depth-oriented'],'mid',NULL,NULL),
('jung_persona','The Persona You Show the World Can Become a Prison','Jung described the Persona as the mask we wear for society — the professional face, the composed parent, the reliable friend. The problem is not the mask itself but identification with it: when we forget that the mask is not us. When the gap between the persona and the actual self becomes too wide, the psyche rebels — through depression, crisis, or the sudden collapse of the role. Authenticity is not just a virtue. It is a structural requirement for psychological health.','When we forget the mask is not us, the psyche rebels.','Carl Jung','','book',ARRAY['identity','authenticity','persona','roles','unconscious'],ARRAY['burned-out','inauthentic','disconnected','performing','empty'],ARRAY['approval-seeking','people-pleasing','emotional-suppression'],ARRAY['authenticity','integrity','wholeness'],ARRAY[2,3,6,1],ARRAY['depth-oriented','reflective'],'deep',NULL,NULL),
('maslow_hierarchy','You Cannot Self-Actualise If You Are Starving for Safety','Maslow''s hierarchy is often misread as self-help aspiration. Its more serious claim is structural: higher-order needs (belonging, esteem, growth) are genuinely inaccessible when lower-order needs (safety, security, basic connection) are unmet. You cannot meditate your way to serenity while your financial situation is acutely precarious. You cannot focus on meaning while you are chronically isolated. The hierarchy is a map of what to address first.','You cannot meditate your way to serenity while your financial situation is acutely precarious.','Abraham Maslow','','book',ARRAY['needs','safety','growth','wellbeing','priorities'],ARRAY['anxious','stuck','overwhelmed','purposeless','unsafe'],ARRAY['all-or-nothing','future-orientation','avoidance'],ARRAY['safety','growth','belonging'],ARRAY[6,2,1,9],ARRAY['analytical','pragmatic'],'entry',NULL,NULL),
('trauma_bessel','Trauma Is Not Stored in the Mind — It Is Stored in the Body','Bessel van der Kolk''s decades of trauma research produced one central finding: traumatic memory is not narrative, it is somatic. The body keeps the score. Trauma is held in posture, muscle tension, startle responses, and breathing patterns — often without any conscious story attached. This is why talking alone does not resolve it. The body must be brought into the healing. Movement, breath, sensation — these are not metaphors. They are the medicine.','The body keeps the score.','Bessel van der Kolk','','book',ARRAY['trauma','body','healing','nervous-system','recovery'],ARRAY['traumatized','numb','disconnected','overwhelmed','anxious'],ARRAY['avoidance','emotional-suppression','past-focus'],ARRAY['healing','integration','safety'],ARRAY[4,6,9,2],ARRAY['evidence-based','somatic'],'deep',NULL,NULL),
('brene_vulnerability','Vulnerability Is Not Weakness — It Is the Birthplace of Everything','Brené Brown''s research showed that the people who reported the deepest sense of love, belonging, and meaning had one thing in common: they allowed themselves to be seen — imperfect, uncertain, risk-taking. Vulnerability is not the exposure of weakness. It is the willingness to show up when you cannot control the outcome. Every creative act, every honest conversation, every genuine relationship begins there.','Vulnerability is not weakness. It is the willingness to show up when you cannot control the outcome.','Brené Brown','','talk',ARRAY['vulnerability','connection','courage','authenticity','love'],ARRAY['ashamed','guarded','performing','disconnected','fearful'],ARRAY['emotional-suppression','people-pleasing','perfectionism'],ARRAY['authenticity','connection','courage'],ARRAY[2,3,4,6],ARRAY['relational','evidence-based'],'mid',NULL,NULL),
('cbt_cognitive_distortions','The Story You Tell Is Not the Same as What Happened','Aaron Beck''s cognitive therapy rests on a simple insight: it is not events that cause suffering but the interpretation of events. Between what happens and how you feel is a thought — often automatic, often distorted. Catastrophising turns a setback into a catastrophe. All-or-nothing thinking makes partial success into total failure. Personalisation makes other people''s behaviour about you. These are not character flaws — they are learned mental habits that can be unlearned.','It is not events that cause suffering but the interpretation of events.','Aaron Beck (Cognitive Therapy)','','book',ARRAY['thoughts','interpretation','cognitive-distortions','emotions','CBT'],ARRAY['anxious','self-critical','depressed','overwhelmed','stuck'],ARRAY['catastrophising','all-or-nothing','personalisation','should-statements'],ARRAY['clarity','self-awareness','growth'],ARRAY[1,4,6,2],ARRAY['analytical','evidence-based'],'entry',NULL,NULL),
('social_fundamental_attribution','You Judge Others by Their Actions and Yourself by Your Intentions','The Fundamental Attribution Error is one of the most replicated findings in psychology: when others behave badly, we attribute it to character (''they''re a selfish person''); when we behave badly, we attribute it to circumstances (''I was having a terrible day''). We extend ourselves enormous moral latitude and extend others very little. This is not a personality flaw — it is universal. But naming it gives you a choice.','We extend ourselves enormous moral latitude and extend others very little.','Lee Ross (Stanford Social Psychology)','','paper',ARRAY['bias','judgment','relationships','empathy','attribution'],ARRAY['judgmental','resentful','comparing','conflicted'],ARRAY['personalisation','all-or-nothing','projection'],ARRAY['empathy','self-awareness','fairness'],ARRAY[1,2,3,8],ARRAY['analytical','evidence-based'],'entry',NULL,NULL),
('social_conformity','Most People Would Rather Be Wrong Together Than Right Alone','Solomon Asch''s conformity experiments showed that a significant percentage of people will give obviously wrong answers to simple questions if the people around them have already given that wrong answer. We don''t just follow the crowd to fit in — we actually begin to doubt our own perception. Social reality has a gravity that distorts individual judgement. Understanding this is not cynicism; it is necessary for anyone who wants to think independently.','Social reality has a gravity that distorts individual judgement.','Solomon Asch (Social Psychology)','','paper',ARRAY['conformity','group-think','independence','identity','courage'],ARRAY['conflicted','pressured','inauthentic','doubtful','comparing'],ARRAY['approval-seeking','people-pleasing','social-evaluation'],ARRAY['authenticity','courage','independence'],ARRAY[2,3,6,9],ARRAY['analytical','evidence-based'],'mid',NULL,NULL),
('social_loneliness_epidemic','Loneliness Is a Public Health Crisis — Not a Personal Failure','More people today report having no one to confide in than at any point in recorded social history. Loneliness has been shown to increase mortality risk more than smoking 15 cigarettes a day. And yet the dominant cultural narrative treats loneliness as a personal embarrassment — a sign that you''re not interesting enough, not social enough, not enough. This is exactly backwards. Loneliness is a social disease, and it thrives on the shame that prevents people from admitting it.','Loneliness thrives on the shame that prevents people from admitting it.','John Cacioppo (University of Chicago)','','book',ARRAY['loneliness','connection','social','shame','health'],ARRAY['lonely','ashamed','isolated','disconnected'],ARRAY['personalisation','withdrawal','avoidance'],ARRAY['connection','belonging','vulnerability'],ARRAY[2,4,5,9],ARRAY['evidence-based','relational'],'entry',NULL,NULL),
('social_power_structures','The Personal Is Political — Your Private Life Is Shaped by Public Forces','Second-wave feminism introduced a phrase that applies well beyond gender: the personal is political. The decisions that feel purely private — when to work, whether to rest, how to eat, what to want — are shaped by economic structures, cultural norms, and power arrangements that are mostly invisible. Feeling inadequate about your productivity is partly about you and partly about a culture that has monetised every waking hour. Separating the two is a form of clarity.','Feeling inadequate about your productivity is partly about you and partly about a culture that has monetised every waking hour.','Carol Hanisch / Second-Wave Feminism','','essay',ARRAY['power','society','politics','identity','culture'],ARRAY['self-critical','overwhelmed','burned-out','inadequate','stuck'],ARRAY['self-blame','personalisation','all-or-nothing'],ARRAY['justice','clarity','self-compassion'],ARRAY[1,2,4,6],ARRAY['systems-thinking','analytical'],'mid',NULL,NULL),
('be_loss_aversion','Losses Hurt Twice As Much As Equivalent Gains Feel Good','Kahneman and Tversky''s Prospect Theory established that the pain of losing ₹100 is roughly twice as intense as the pleasure of gaining ₹100. This ''loss aversion'' explains a vast range of human behaviour: why we stay in bad situations too long, why we hold on to losing investments, why criticism stings more than praise lifts. Evolution built us to weight losses heavily because, on the savannah, a loss could be fatal. But in modern life, this bias distorts almost every decision we make.','The pain of losing is twice as intense as the pleasure of an equivalent gain.','Daniel Kahneman & Amos Tversky','','paper',ARRAY['decision-making','bias','loss','risk','behaviour'],ARRAY['fearful','risk-averse','stuck','clinging','anxious'],ARRAY['loss-aversion','status-quo-bias','catastrophising'],ARRAY['clarity','courage','growth'],ARRAY[5,6,1,9],ARRAY['analytical','evidence-based'],'entry',NULL,NULL),
('be_present_bias','You Systematically Overvalue the Present and Undervalue the Future','Behavioural economics calls it hyperbolic discounting: we overweight immediate rewards relative to future ones in a predictable and irrational pattern. Given the choice between ₹100 today and ₹120 next week, many choose ₹100. Given the choice between ₹100 in a year and ₹120 in a year and a week, almost everyone waits for ₹120. The time gap is identical — but our preference reverses. This is why we fail at diets, savings, and long-term projects. The future self feels like a stranger.','The future self feels like a stranger — so you discount their needs accordingly.','Richard Thaler & Cass Sunstein (Behavioural Economics)','','book',ARRAY['time','decision-making','habits','willpower','future'],ARRAY['impatient','impulsive','restless','stuck','conflicted'],ARRAY['present-bias','short-term-thinking','procrastination'],ARRAY['intentionality','growth','patience'],ARRAY[7,3,9,6],ARRAY['analytical','evidence-based'],'mid',NULL,NULL),
('be_scarcity_mindset','Scarcity Hijacks Your Mind — Even When the Scarcity Isn''t Physical','Sendhil Mullainathan and Eldar Shafir''s research showed that scarcity — of money, time, or social connection — doesn''t just restrict resources. It hijacks cognitive bandwidth. People in scarcity situations perform worse on IQ tests, make worse decisions, and are less able to think long-term. This is not a character flaw of the poor or busy; it is a predictable cognitive consequence of operating under resource pressure. Understanding this reframes a lot of self-blame.','Scarcity hijacks cognitive bandwidth — this reframes a lot of self-blame.','Mullainathan & Shafir (Harvard / Princeton)','','book',ARRAY['scarcity','decision-making','stress','self-compassion','cognition'],ARRAY['overwhelmed','self-critical','stuck','anxious','burned-out'],ARRAY['self-blame','tunnel-vision','short-term-thinking'],ARRAY['self-compassion','clarity','understanding'],ARRAY[1,6,3,9],ARRAY['analytical','evidence-based'],'mid',NULL,NULL),
('naval_specific_knowledge','Play Long-Term Games With Long-Term People','The returns in life come from compound interest — in relationships, in knowledge, in money, in reputation. But compounding requires time, and time requires commitment. Most people opt for short-term thinking without realizing it. The irony is that the difficulty is usually where the compound return begins. The people who win at 40 are usually the ones who picked something at 25 and stayed.','The difficulty is usually where the compound return begins.','Naval Ravikant','https://nav.al','essay',ARRAY['commitment','compounding','patience','long-term thinking','mastery'],ARRAY['impatient','comparing','stuck','restless','doubting'],ARRAY['short-term-bias','grass-is-greener','comparison'],ARRAY['mastery','integrity','patience'],ARRAY[3,5,7,9],ARRAY['analytical','first-principles'],'mid',NULL,NULL),
('pol_arendt_banality','Evil Is Rarely Demonic — It Is Usually the Absence of Thought','Hannah Arendt, covering the Eichmann trial, expected to find a monster. She found a bureaucrat. Eichmann did not hate Jews — he was simply not thinking. He was following procedures, advancing his career, obeying norms. Her phrase ''the banality of evil'' described this: that the greatest moral failures are often not driven by malice but by the suspension of individual judgement in the face of authority and social expectation.','The greatest moral failures are often not malice — they are the suspension of individual judgement.','Hannah Arendt','','book',ARRAY['morality','authority','conformity','thinking','responsibility'],ARRAY['compliant','pressured','conflicted','doubtful','passive'],ARRAY['people-pleasing','approval-seeking','avoidance'],ARRAY['courage','integrity','responsibility'],ARRAY[6,9,1,3],ARRAY['philosophical','analytical'],'deep',NULL,NULL),
('pol_rawls_veil','Would You Accept This System If You Didn''t Know Where You''d Land In It?','John Rawls asked: if you didn''t know whether you''d be born rich or poor, male or female, advantaged or disadvantaged, what kind of society would you design? This ''veil of ignorance'' is a thought experiment for testing fairness — not just in policy, but in your own decisions and relationships. Would you treat a person differently if you didn''t know their position? Often the honest answer is uncomfortable.','Would you accept this system if you didn''t know where you''d land in it?','John Rawls','','book',ARRAY['fairness','justice','empathy','society','ethics'],ARRAY['conflicted','privileged','judging','comparing'],ARRAY['attribution-bias','in-group-out-group','all-or-nothing'],ARRAY['justice','empathy','fairness'],ARRAY[1,2,5,8],ARRAY['philosophical','analytical'],'deep',NULL,NULL),
('pol_foucault_power','Power Works Best When You Police Yourself','Foucault argued that the most efficient form of power is not the authority that punishes you — it is the authority you have so thoroughly internalised that you punish yourself. The panopticon: a prison where inmates can never be sure if they''re being watched, so they behave as if they always are. Modern equivalents are everywhere: the performance review, the social media profile, the internalised voice that says ''what will people think?'' You are simultaneously the guard and the prisoner.','You are simultaneously the guard and the prisoner.','Michel Foucault','','book',ARRAY['power','society','self-surveillance','freedom','conformity'],ARRAY['self-critical','performing','anxious','constrained','inauthentic'],ARRAY['self-blame','approval-seeking','people-pleasing'],ARRAY['freedom','authenticity','courage'],ARRAY[1,3,6,4],ARRAY['philosophical','systems-thinking'],'deep',NULL,NULL),
('pol_amartya_capabilities','Freedom Is Not the Absence of Constraint — It Is the Presence of Capability','Amartya Sen''s capabilities approach reframes what we mean by freedom. Formal freedom — no one is stopping you — means little if you lack the real capability to act. A person can be ''free'' to attend university but unable to because of poverty, care responsibilities, or cultural pressure. Sen argues we should measure human wellbeing not by income or formal rights, but by what people are actually able to do and be. The gap between formal and real freedom is where most human unfreedom lives.','The gap between formal and real freedom is where most human unfreedom lives.','Amartya Sen','','book',ARRAY['freedom','capability','justice','wellbeing','society'],ARRAY['trapped','constrained','purposeless','frustrated','unfulfilled'],ARRAY['learned-helplessness','all-or-nothing','self-blame'],ARRAY['freedom','justice','dignity'],ARRAY[1,4,8,6],ARRAY['analytical','systems-thinking'],'deep',NULL,NULL)
